sp_widget.client_script:
api.controller = function($scope, $location) {
    var c = this;
    c.selectedAccount = null;
    c.view = 'list';
    c.form = { amount: '', description: '' };
    c.serverErrors = [];
    c.submitting = false;
    c.successMessage = '';
    c.approvalContext = null;

    c.selectAccount = function(acct) {
        c.selectedAccount = acct;
        c.view = 'detail';
        c.form = { amount: '', description: '' };
        c.serverErrors = [];
        c.successMessage = '';
    };

    c.backToList = function() {
        c.selectedAccount = null;
        c.view = 'list';
        c.form = { amount: '', description: '' };
        c.serverErrors = [];
        c.successMessage = '';
        c.approvalContext = null;
        // Clear URL params when going back
        $location.search({id: 'x_274351_finance_0_ach_page'});
    };

    c.performAction = function(action) {
        c.serverErrors = [];
        c.successMessage = '';
        c.submitting = true;

        var payload = {
            action: action,
            account: c.selectedAccount.sys_id,
            amount: c.form.amount,
            description: c.form.description
        };

        c.server.update(payload).then(function(response) {
            c.submitting = false;
            if (response.submitResult && response.submitResult.success) {
                if (action === 'deposit') {
                    c.successMessage = 'Deposit of $' + response.submitResult.amount + ' completed successfully!';
                } else if (action === 'withdraw') {
                    c.successMessage = 'Withdrawal of $' + response.submitResult.amount + ' completed successfully!';
                } else if (action === 'deactivate') {
                    c.successMessage = 'Account has been deactivated.';
                }
                c.form = { amount: '', description: '' };
                if (response.accounts) {
                    c.data.accounts = response.accounts;
                    for (var i = 0; i < c.data.accounts.length; i++) {
                        if (c.data.accounts[i].sys_id === c.selectedAccount.sys_id) {
                            c.selectedAccount = c.data.accounts[i];
                            break;
                        }
                    }
                }
            } else if (response.submitResult && response.submitResult.errors) {
                c.serverErrors = response.submitResult.errors;
            }
        }, function() {
            c.submitting = false;
            c.serverErrors = ['An unexpected error occurred.'];
        });
    };

    c.deposit = function() { c.performAction('deposit'); };
    c.withdraw = function() { c.performAction('withdraw'); };
    c.deactivate = function() {
        if (confirm('Are you sure you want to deactivate this account?')) {
            c.performAction('deactivate');
        }
    };

    // Check for approval context URL parameters on init
    var params = $location.search();
    if (params.account_sys_id && params.amount && params.action_type) {
        c.approvalContext = params.action_type;
        c.form.amount = params.amount;

        // Find and auto-select the matching account
        if (c.data && c.data.accounts) {
            for (var j = 0; j < c.data.accounts.length; j++) {
                if (c.data.accounts[j].sys_id === params.account_sys_id) {
                    c.selectAccount(c.data.accounts[j]);
                    c.form.amount = params.amount;
                    c.approvalContext = params.action_type;
                    break;
                }
            }
        }
    }
};

sp_widget.css:
.ach-transfer-container {
    .panel-heading {
        background-color: #1a3a5c;
        color: #ffffff;
        .panel-title {
            font-size: 16px;
            font-weight: 600;
        }
    }
    .table > tbody > tr {
        cursor: pointer;
        &:hover { background-color: #f0f5fa; }
    }
    .account-detail-panel {
        background: #f9fbfd;
        border: 1px solid #dce4ec;
        border-radius: 4px;
        padding: 20px;
        margin-bottom: 15px;
        .detail-header {
            font-size: 15px;
            font-weight: 600;
            color: #1a3a5c;
            margin-bottom: 15px;
            padding-bottom: 8px;
            border-bottom: 2px solid #1a3a5c;
        }
        .detail-row {
            display: flex;
            padding: 6px 0;
            .detail-label {
                font-weight: 600;
                color: #555;
                width: 140px;
                flex-shrink: 0;
            }
            .detail-value { color: #333; }
        }
    }
    .action-panel {
        background: #fff;
        border: 1px solid #dce4ec;
        border-radius: 4px;
        padding: 20px;
        .action-header {
            font-size: 14px;
            font-weight: 600;
            color: #244b6e;
            margin-bottom: 15px;
        }
    }
    .btn-deactivate {
        margin-top: 15px;
    }
    .status-badge {
        &.active { color: #3c763d; font-weight: 600; }
        &.inactive { color: #a94442; font-weight: 600; }
    }
    .empty-state { padding: 30px 0; }
}

sp_widget.script:
"(function() {
 data.accounts = [];
 data.isManager = gs.hasRole('x_274351_finance_0.manager') && !gs.hasRole('x_274351_finance_0.administrator');

 var gr = new GlideRecord('x_274351_finance_0_accounts');
 if (!data.isManager) {
 gr.addQuery('holder', gs.getUserID());
 }
 gr.orderBy('number');
 gr.query();
 while (gr.next()) {
 data.accounts.push({
 sys_id: gr.getUniqueValue(),
 number: gr.getValue('number'),
 account_type: gr.getDisplayValue('account_type'),
 holder_name: gr.getDisplayValue('holder'),
 balance: parseFloat(gr.getValue('balance') || 0).toFixed(2),
 active: gr.getValue('active') == '1' || gr.getValue('active') == 'true'
 });
 }

 if (input && input.action) {
 if (input.action === 'deposit' || input.action === 'withdraw') {
 if (gs.hasRole('x_274351_finance_0.administrator')) {
 data.submitResult = { success: false, errors: ['Administrators cannot perform this action.'] };
 return;
 }
 if (!gs.hasRole('x_274351_finance_0.manager')) {
 data.submitResult = { success: false, errors: ['Only managers can perform this action.'] };
 return;
 }

 var errors = [];
 if (!input.account) errors.push('Please select an account.');
 if (!input.amount || parseFloat(input.amount) <= 0) errors.push('Please enter a valid amount.');

 if (errors.length > 0) {
 data.submitResult = { success: false, errors: errors };
 return;
 }

 var acctGr = new GlideRecord('x_274351_finance_0_accounts');
 if (!acctGr.get(input.account)) {
 data.submitResult = { success: false, errors: ['Account not found.'] };
 return;
 }
 if (acctGr.getValue('active') != '1' && acctGr.getValue('active') != 'true') {
 data.submitResult = { success: false, errors: ['Account is not active.'] };
 return;
 }

 var amount = parseFloat(input.amount);
 if (input.action === 'withdraw') {
 var currentBalance = parseFloat(acctGr.getValue('balance'));
 if (currentBalance < amount) {
 data.submitResult = { success: false, errors: ['Insufficient funds. Balance: $' + currentBalance.toFixed(2)] };
 return;
 }
 }

 var txnGr = new GlideRecord('x_274351_finance_0_txn');
 txnGr.initialize();
 txnGr.setValue('account', input.account);
 txnGr.setValue('type', input.action === 'deposit' ? 'deposit' : 'withdrawal');
 txnGr.setValue('amount', amount);
 txnGr.setValue('status', 'completed');
 txnGr.setValue('description', input.description || '');
 var txnId = txnGr.insert();

 if (!txnId) {
 data.submitResult = { success: false, errors: ['Failed to create transaction.'] };
 return;
 }

 data.submitResult = { success: true, type: input.action, amount: amount.toFixed(2) };
 }

 if (input.action === 'deactivate') {
 if (gs.hasRole('x_274351_finance_0.administrator')) {
 data.submitResult = { success: false, errors: ['Administrators cannot perform this action.'] };
 return;
 }
 if (!gs.hasRole('x_274351_finance_0.manager')) {
 data.submitResult = { success: false, errors: ['Only managers can perform this action.'] };
 return;
 }

 var deactGr = new GlideRecord('x_274351_finance_0_accounts');
 if (!deactGr.get(input.account)) {
 data.submitResult = { success: false, errors: ['Account not found.'] };
 return;
 }
 deactGr.setValue('active', false);
 deactGr.update();
 data.submitResult = { success: true, type: 'deactivate' };
 }

 // Re-fetch accounts after action
 data.accounts = [];
 var gr2 = new GlideRecord('x_274351_finance_0_accounts');
 if (!data.isManager) {
 gr2.addQuery('holder', gs.getUserID());
 }
 gr2.orderBy('number');
 gr2.query();
 while (gr2.next()) {
 data.accounts.push({
 sys_id: gr2.getUniqueValue(),
 number: gr2.getValue('number'),
 account_type: gr2.getDisplayValue('account_type'),
 holder_name: gr2.getDisplayValue('holder'),
 balance: parseFloat(gr2.getValue('balance') || 0).toFixed(2),
 active: gr2.getValue('active') == '1' || gr2.getValue('active') == 'true'
 });
 }
 }
})();
"
